#!/usr/bin/env python3
from pathlib import Path
import json,datetime,pandas as pd,numpy as np
from sklearn.model_selection import train_test_split
P=Path(__file__).resolve().parents[2];O=P/'outputs/round3';W=P/'work/round3';SEED=20261025
def main():
 assert json.loads((P/'outputs/gate_ledger.json').read_text())['round3_F']['written_before_round3_calculation'];assert not (O/'R2_execution_contract.json').exists()
 k0=pd.read_csv(P/'outputs/round2_A1/provenance_inputs/K0_primary_with_released_age.csv');don=k0.groupby('donor')['sample.subjectAgeAtDraw'].min().rename('age_at_first_eligible_visit').reset_index().sort_values('donor');don['age_stratum']=np.where(don.age_at_first_eligible_visit<45,'young_25_35','older_55_67');si,ei=train_test_split(np.arange(len(don)),test_size=.5,random_state=SEED,stratify=don.age_stratum);don['split']='E';don.loc[si,'split']='S';assert don.split.value_counts().to_dict()=={'E':34,'S':34} or sorted(don.split.value_counts())==[34,34];don.to_csv(O/'R2_K0_donor_split.csv',index=False)
 ages=pd.read_csv(P/'work/round2_A1/cache/OneK1K_selected_obs.csv.gz',usecols=['donor_id','age']).drop_duplicates();assert ages.groupby('donor_id').size().max()==1;ages=ages.sort_values('donor_id').reset_index(drop=True);ages['age_stratum']=pd.qcut(ages.age,5,labels=False,duplicates='drop');tr,te=train_test_split(np.arange(len(ages)),test_size=.2,random_state=SEED,stratify=ages.age_stratum);ages['split']='test20';ages.loc[tr,'split']='train80';rng=np.random.default_rng(np.random.SeedSequence([SEED,3201]));ages['CV_fold']=-1
 for _,a in ages[ages.split.eq('train80')].groupby('age_stratum'):
  ix=rng.permutation(a.index);ages.loc[ix,'CV_fold']=np.arange(len(ix))%5
 ages.to_csv(O/'R2_OneK1K_donor_split.csv',index=False)
 contract={'seed':SEED,'frozen_UTC':datetime.datetime.now(datetime.timezone.utc).isoformat(),'F':'as previously recorded in gate_ledger.json round3_F; unchanged','K0_split':'34 S and34 E; sklearn stratified random half split by preexisting young/older bands, donor minimum eligible released age, random_state20261025; no rerandomization','OneK1K_split':'all981 known-age donors;80/20 stratified by age quintile before QC and modeling; fixed five donor folds inside train80','Census_release':'2025-11-08','reference_genes':'stable Ensembl IDs present in both OneK1K and frozen HIHA source annotations, never published age-selected gene lists; common feature availability only, not E expression/outcomes','native_cell_QC':'200<=full-row n_features<=5000 and mitochondrial fraction<=25%; at least3 expressed cells per training gene; no donor/cell exclusion based on prediction or ICC','pseudocell':'100 draws of15 cells per donor×visit×type; native dynamic replacement <=15. Same membership across a,b,c,d. log1p CP10K using full released raw_sum. Continuous mean prediction, matching A1 audit; mean absolute error primary, median absolute error supplementary','S_gene_ICC':'Only S donors with frozen7–9d pair; pooled raw-count donor×visit×type pseudobulk log2(1+CPM), full per-type library denominator; vectorized ICC(2,1), undefined ICC excluded from threshold variants; no E gene ICC','baseline_replication_scope':'OneK1K-only reimplementation of published Pearson-age feature-selection + LASSO branch, not exact recreation of published5-cohort pretrained model or MIRP/MIRA branches. Published final model uses alpha1, standardizeFALSE,100x15 pseudocells, inverse-age-frequency weights,5fold MAE selection. Donor-blocked CV and fold-local feature selection added to prevent pseudocell leakage.','feature_selection':'Within each OneK training fold (and final train80 refit), Pearson correlation of donor mean CP10K with age, BH q<0.05, rank by abs correlation, stable Ensembl tie-break; gene expression>=3cells. Choose baseline feature count via5fold donor MAE over100,200,...2000 plus all significant if<100; no E/AIDA/test20 use.','penalty':'LASSO endpoint alpha1 of elastic net, interceptTRUE, no feature standardization (except training-only gene standardization before PCA);100 log-spaced lambda/lambda_max values1 to1e-4. Native glmnet validation of optimized Gram solver required before accepting results. Donor CV uses mean donor prediction and equal donor score weighting; fitting inverse observed-age-frequency weights computed inside each training fold.','variant_b_c':'Use the same baseline chosen feature-count rule and OneK fold-local ranks, intersect with S gene ICC>=0.5 or>=0.7 respectively; retune lambda only using OneK train folds; no selection by E performance','variant_d':'Same baseline gene-selection/count; center and standardize OneK training donor mean log1pCP10K profiles, fit PCA with min(50,n_training_donors-1,n_genes) components; project pseudocells then LASSO. PCA refit inside folds, no E/test/AIDA use.','variant_e':'Same baseline selected/count genes; one pooled raw donor pseudobulk log2(1+CPM) rather than100 pseudocells; fit LASSO using inverse-age-frequency donor weights. No pseudocell randomness. This changes aggregation and expression scale, explicitly reported.','evaluation':'E only all eligible visits for LODO weighted age+intercept residual; each held donor all visits excluded. Same original frozen75–105d and330–400d pairs within E;2000 E-donor-cluster bootstrap and refit LODO each time. Paired delta ICC bootstrap shared across variants. F point threshold and matched-type OneK test MAE guardrail unchanged.','accuracy':'OneK fixed20% holdout, Allen E all visits with equal total donor weight, AIDA noncommercial healthy known-exact-age donors; predictions grouped by independent donor, never cells/pseudocells for accuracy N. Report source feature coverage, all original cohorts remain separate.','AIDA':'public CELLxGENE AIDA Phase1 Freezev2, fixed Census dataset/version; annotated PBMC healthy known-age donors; exclude commercial/common-control donors identified by source metadata, retain a row-level reason ledger. No external model selection.','failure_semantics':'Numerical/access/baseline replication failure or insufficient pairs is NOT_EVALUABLE, not repair FAIL. Completed valid F comparison yields PASS orFAIL; no rescue threshold, cohort or outcome changes.'}
 (O/'R2_execution_contract.json').write_text(json.dumps(contract,indent=2,ensure_ascii=False));p=P/'outputs/gate_ledger.json';d=json.loads(p.read_text());d['round3_F']['execution_contract']='outputs/round3/R2_execution_contract.json';d['round3_F']['status']='R2_CONTRACT_AND_DONOR_SPLITS_FROZEN';p.write_text(json.dumps(d,indent=2,ensure_ascii=False));print('S/E',don.groupby(['split','age_stratum']).size().to_dict());print('OneK',ages.split.value_counts().to_dict())
if __name__=='__main__':main()
